const weaponUserType=u=>['soldier','commando','snow-sniper'].includes(u?.type);
const burstRules=window.TriumphBalance.burstRules;
const tankSweepRules=window.TriumphBalance.tankSweepRules;
const {enemyFireDelay,trackBurst,burstReady,finishBurstShot,tankGroup,aimTank,aimCannon,humanFiringLane,aimHuman,fire,burst,sprayDensity}=window.TriumphCombat.create({getState:()=>s,burstRules,tankSweepRules,cannonSweepRules:window.TriumphBalance.cannonSweepRules,rnd,visible,dist,blocked,navigate,cardinal,diagonal,cannonAngle,getDifficulty:()=>document.querySelector('#difficulty').value,bugFireBases:window.TriumphBalance.bugFireBases,specialistRules,desertRiders:window.TriumphDesertRiders,originalAudio:()=>window.ORIGINAL_AUDIO,sound,tone,emitAcousticEvent:(origin,r)=>emitAcousticEvent(origin,r)});
function stepProjectiles(dt){window.TriumphProjectiles.step(s,dt,{W,H,blocked,dist,damage,destroyProp,wormExposed:window.TriumphDesertWorm.exposed,sound,tone,burst,emitAcousticEvent:(origin,r)=>emitAcousticEvent(origin,r)});}

function nearest(u,list,max=Infinity){let best=null,d=max;for(const a of list){if(a.alive===false||a.hp<=0)continue;const t=dist(u,a);if(t<d){best=a;d=t;}}return best;}

function bugArrival(x,y){const point={x:Math.max(16,Math.min(W-16,x)),y:Math.max(44,Math.min(H-24,y))};return window.TriumphNavigation?.destination(point,point,blocked)||point;}
function wormBlocked(x,y){return x<0||x>=W||y<36||y>=H||blocked(x,y);}
function wormRouteBlocked(x,y){return !window.TriumphDesertWorm.clear(x,y,wormBlocked);}
function spawnDesertRider(type,x,y,route=[]){const u=window.TriumphDesertRiders.create(type,x,y,wormBlocked,route);if(u)s.humans.push(u);return u;}
function spawnDesertWorm(x,y){const u=window.TriumphDesertWorm.create(x,y,wormBlocked);if(u)s.aliens.push(u);return u;}
function spawnGroundBug(x,y){({x,y}=bugArrival(x,y));const special=rnd()<specialistRules.redbug.spawnChance,u=unit(x,y,'alien',special?'redbug':'soldier');u.hp=special?specialistRules.redbug.hp:s.difficulty?.bug||4;s.aliens.push(u);return u;}
function alertPack(sourceBug,threat,radius=160){
 if(!s||!s.aliens||!threat||threat.alive===false)return;
 for(const other of s.aliens){
  if(!other.alive||other===sourceBug||other.type==='desert-worm')continue;
  if(dist(other,sourceBug)<=radius||dist(other,threat)<=radius){
   other.ai=other.ai||{};
   if(!other.ai.target||!other.ai.target.alive||dist(other,threat)<dist(other,other.ai.target)){
    other.ai.target=threat;other.ai.boredUntil=0;other.ai.hesitateUntil=0;other.ai.focusUntil=Math.max(other.ai.focusUntil||0,s.t+3);
    other.intent={mode:'approach',until:s.t+2+rnd()*2,goal:{x:threat.x+(rnd()-.5)*20,y:threat.y+(rnd()-.5)*20}};
    other.angle=Math.atan2(threat.y-other.y,threat.x-other.x);
   }
  }
 }
}
function emitAcousticEvent(origin,radius=280){
 if(!s||!s.aliens||!origin)return;
 const soundX=origin.x,soundY=origin.y;
 for(const a of s.aliens){
  if(!a.alive||a.type==='desert-worm')continue;
  const d=dist(a,{x:soundX,y:soundY});
  if(d<=radius&&visible(a,{x:soundX,y:soundY})){
   a.ai=a.ai||{};a.ai.boredUntil=0;a.ai.hesitateUntil=0;
   a.angle=Math.atan2(soundY-a.y,soundX-a.x);
   const perceiveRange=a.type==='redbug'?specialistRules.redbug.sight:175;
   const target=perceive(a,s.humans.filter(u=>u.alive),perceiveRange);
   if(target){
    a.ai.target=target;a.ai.focusUntil=Math.max(a.ai.focusUntil||0,s.t+2);
    a.intent={mode:'approach',until:s.t+2+rnd()*2,goal:{x:target.x,y:target.y}};
    alertPack(a,target,160);
   }else{
    a.intent={mode:'approach',until:s.t+3+rnd()*2,goal:{x:soundX,y:soundY}};
   }
  }
 }
}
function kill(u,owner){if(!u.alive||(u.type==='desert-worm'&&!window.TriumphDesertWorm.exposed(u)))return;cancelSupply(u);u.alive=false;sound(u.team==='alien'?(u.type==='queen'?20:5):6,.22);burst(u.x,u.y,10,u.team==='alien'?'#b57068':'#7d3f35');if(u.team==='alien'){s.kills++;if(s.waveKills)s.waveKills[u.type==='queen'?'queen':'normal']++;if(owner)s.score[owner-1]+=10;if(u.type==='queen')for(let i=0;i<4;i++){spawnGroundBug(u.x+rnd()*30-15,u.y+rnd()*30-15);}}if(u.type==='commander'){u.respawn=10;if(u.id===inputState.activeCommander)inputState.drag=null;}}
function damage(u,n,owner){if(!u.alive||u.shieldUntil>s.t||(u.type==='desert-worm'&&!window.TriumphDesertWorm.exposed(u)))return;u.hp-=n;if(u.team==='alien'){let threat=null;if(owner)threat=s.humans.find(h=>h.id===owner&&h.alive);if(!threat)threat=nearest(u,s.humans.filter(h=>h.alive));if(threat){u.ai=u.ai||{};u.ai.target=threat;u.ai.boredUntil=0;u.ai.hesitateUntil=0;u.ai.focusUntil=Math.max(u.ai.focusUntil||0,s.t+3);alertPack(u,threat,160);}}if(u.hp<=0)kill(u,owner);}
function destroyProp(p){if(p.destroyed)return;p.destroyed=true;burst(p.x,p.y,p.wall?20:65);sound(p.wall?41:25,.5);if(!p.wall){s.fires.push({x:p.x,y:p.y,until:s.t+4,object:274});for(const a of s.aliens)if(a.alive&&dist(a,p)<65)damage(a,8,0);for(const n of s.nests)if(n.hp>0&&dist(n,p)<75){n.hp-=12;emitAcousticEvent(n,280);}for(const q of s.props)if(q!==p&&q.hp>0&&dist(q,p)<60){q.hp=0;destroyProp(q);}}emitAcousticEvent(p,280);}
function grenade(u){if(!u.alive||u.grenades<=0)return;u.grenades--;const x=u.x+Math.cos(u.angle)*90,y=u.y+Math.sin(u.angle)*90;burst(x,y,58);emitAcousticEvent({x,y},280);for(const a of s.aliens)if(a.alive&&dist(a,{x,y})<75)damage(a,12,u.id);for(const n of s.nests)if(n.hp>0&&dist(n,{x,y})<80){n.hp-=15;emitAcousticEvent(n,280);if(n.hp<=0)burst(n.x,n.y,32);}for(const p of s.props||[])if(p.hp>0&&dist(p,{x,y})<80){p.hp-=15;if(p.hp<=0)destroyProp(p);}sound(23,.5);if(!window.ORIGINAL_AUDIO)tone(65,.25,.06);}


const supportLifecycle=window.TriumphSupportLifecycle.create({getState:()=>s,original,W,H,random:rnd,paths:window.TriumphSupport,navigation:window.TriumphNavigation,blocked,staticBlocked,unit,infantryType,assignRally:u=>assignRally(u),sound,burst,dist,kill,damage,fire,emitAcousticEvent:(origin,r)=>emitAcousticEvent(origin,r)});
function groundArrival(...args){return supportLifecycle.groundArrival(...args);}
function flightEntersMap(...args){return supportLifecycle.flightEntersMap(...args);}
function addTroop(...args){return supportLifecycle.addTroop(...args);}
function reinforcementStatus(...args){return supportLifecycle.reinforcementStatus(...args);}
function reinforcementRule(...args){return supportLifecycle.reinforcementRule(...args);}
function reinforce(...args){return supportLifecycle.reinforce(...args);}
function supportExplosion(...args){return supportLifecycle.supportExplosion(...args);}
function updateSupport(...args){return supportLifecycle.updateSupport(...args);}
function spawnPickupRoll(roll){if(s.customMission&&!s.customMission.randomPickups)return;const rules=window.ORIGINAL_PICKUPS?.[s.originalMap?.index];if(!rules)return;const troops=s.humans.filter(u=>u.alive&&infantryType(u)).length,compare=window.TriumphSupport.compare;for(const rule of rules.cases){if(rule.type==='growplant'&&(document.querySelector('#difficulty').value!=='normal'||!(rule.globals||[]).every(g=>compare(s.support.globals[g.index]||0,g.comparison,g.value))))continue;if(s.t<rule.minimumTime||!rule.checks.every(c=>compare(c.variable===0?roll:rules.secondary,c.comparison,c.difficulty?s.difficulty[c.difficulty]:c.value)))continue;if(rule.count&&!compare((rule.type==='growplant'?s.flowers.filter(f=>f.alive):s.pickups.filter(p=>p.type===rule.type)).length,rule.count.comparison,rule.count.value))continue;if(rule.troops){const tokens=rule.troops.tokens,limit=tokens.length===1?tokens[0].value:s.rules.maxAliens*tokens.at(-1).value;if(!compare(troops,rule.troops.comparison,limit))continue;}if(['troops','air','tank','blitz'].includes(rule.type)&&!reinforcementRule(rule.type))continue;const helper=s.supportHelpers[rule.parent];let point=helper?{x:helper.x+rule.x,y:helper.y+rule.y}:null;const clear=p=>p&&p.x>20&&p.x<W-20&&p.y>45&&p.y<H-20&&!blocked(p.x,p.y)&&!blocked(p.x-8,p.y-8)&&!blocked(p.x+8,p.y+8);if(!clear(point)){point=null;for(let attempt=0;attempt<64;attempt++){const p={x:24+rnd()*(W-48),y:48+rnd()*(H-72)};if(clear(p)){point=p;break;}}}if(point){if(rule.type==='growplant')s.flowers.push({...point,alive:true,object:rule.object});else s.pickups.push({...point,type:rule.type,object:rule.object});}}}
function updatePickupSpawns(dt){if(s.customMission&&!s.customMission.randomPickups)return;const rules=window.ORIGINAL_PICKUPS?.[s.originalMap?.index];if(!rules)return;s.pickupClock-=dt;while(s.pickupClock<=0){s.pickupClock+=rules.interval;spawnPickupRoll(Math.floor(rnd()*rules.range));}}
function hasRespawnSupport(...args){return supportLifecycle.hasRespawnSupport(...args);}
function respawnCommander(...args){return supportLifecycle.respawnCommander(...args);}
const pickupWeapon=type=>({auto:0,rapid:1,flame:1,plasma:2})[type];
const duplicateCommanderWeapon=(u,p)=>u.type==='commander'&&pickupWeapon(p.type)!==undefined&&u.weapon===pickupWeapon(p.type);
function pickup(u,p){if(duplicateCommanderWeapon(u,p))return false;if(['blitz','troops','tank','air'].includes(p.type)){if(!reinforce(p.type,p))return false;}else if(p.type==='grenade')u.grenades=Math.min(8,u.grenades+1);else {u.weapon=['rapid','flame'].includes(p.type)?1:p.type==='auto'?0:2;u.weaponTime=Infinity;}if(u.id)s.score[u.id-1]+=25;burst(p.x,p.y,15,'#ffed7b');tone(650,.1);return true;}
const bugFireBases=window.TriumphBalance.bugFireBases;


function showUnits(){
 input.openModal('units');
 const difficulty=document.querySelector('#difficulty').value,h=s.difficulty||sourceRules.difficulty[difficulty],base=bugFireBases[difficulty]||3.8;
 const burstText=type=>{const r=burstRules[type];return `${r.min}–${r.max} shots per burst; ${r.restMin}–${r.restMax} s rest; ${r.delayMin}–${r.delayMax} s reaction delay.`;};
 const rows=[
 ['Commander','Commander1',1,'Bullet: 1; grenade: 12 to bugs, 15 to nests','0.25 s (4 shots/s); flame: 0.18 s','Keyboard / AI fires in eight directions, including diagonals; selected mouse commander aims freely. Moves at 85 px/s, commands nearby troops and collects weapons/support. Returns after 10 s if army or incoming support remain; return shield lasts 0.6 s. Grenades: 0.33 s cooldown, up to 8 carried.'],
 ['Infantry','Troop',1,'1 per bullet','0.38 s (2.63 shots/s); Defend: 0.20 s (5/s)',burstText('soldier')+' Eight-direction fire (including diagonals); moves into an unobstructed weapon-range lane and fires only when aligned. Defend holds and waits for a legal lane. Sees visible enemies within 245 px. Normal patrols, Follow stays with its commander, Attack advances, Defend holds position. Collects weapons/eagles and occupies cannons. Attack-moving soldiers make short route-side detours: eagles before turrets in clear areas, turrets before combat when enemies are nearby. When clear of enemies, temporarily seeks usable eagles within 250 px, then returns. Combat pauses the trip; player orders cancel it.'],
 ['Commando','Troop',1,'1 per bullet','0.38 s (2.63 shots/s); flame: 0.18 s',burstText('commando')+' Blue bandana. Fires in eight directions, including diagonals. Delivered by blue-eagle air and infiltration support; retains normal infantry orders, sight, pickups, health and damage, including automatic eagle trips when no enemies are in range.'],
 ['Tank','Tank',8,'5 per bullet','0.20 s (5 shots/s)',burstText('tank')+' Sweeps a locked 25–80° arc toward the densest visible bug group within 300 px; narrow for tight groups, wider for spread groups. Alternates sweep direction between bursts. Falls back to a nest when no bugs are visible. Uses squad orders and terrain routing. Right-click an enemy to focus a 15° sweep across that target. Walls stop shots.'],
 ['Ground robot','ground bot',7,'1 per bullet','0.38 s; Defend: 0.20 s; flame: 0.18 s',burstText('robot')+' Moves 50% faster than its previous recreation speed (54 px/s travel; 36 px/s patrol). Uses squad orders, terrain routing and eight-direction fire. Detects enemies within 245 px.'],
 ['Krate ground bug','Krate Ground Bug',h.bug,'Spit: 1; melee: 1',`${base.toFixed(1)}–${(base+1.6).toFixed(1)} s spit; melee: 1 s`,'Sees 175 px with clear sight. Spits in its facing direction ±11.25°. Randomly approaches, wanders or pauses. Focus lasts 1.5–3.5 s, then breaks for 1–3 s; may skip shooting. Evolves at a growplant.'],
 ['Ceiling / vent bug','alien shadow','Untargetable aloft','Ground bug after landing','Contact roll every 0.1 s','Missions 7–9: ceiling shadows cross walls and drop beside commanders or infantry. Drop and jump animations cannot be attacked; landed bugs fight normally. In missions 7–8, ordinary ground bugs can return into vents on a 5% roll every 2 s, while ceiling population allows. Clear every ceiling and transition bug to finish the mission.'],
 ['Desert charging worm (custom opt-in)',null,16,'Charge: 2 per ground target','1.2 s warning; 1.5 s recovery','Beneath the Dunes custom mission. Sand ripples: underground and immune. Exposed gold warning locks a horizontal or vertical lane; sidestep before the 300 px/s charge (260 px maximum). Walls stop its 24 px body. Exposed during charge and recovery; no spit, evolution or wall damage.'],
 ['Rider scout (custom opt-in)',null,1,'1 per bullet','0.6 s; evade rest 2.5 s','Beneath the Dunes custom mission. Eight-direction rifle, 180 px sight. Fixed kit; no weapon/eagle collection or cannon mounting. Shared troop orders, focus, force-move and door/terminal use. Automatically retreats 38 px at 100 px/s from visible ground bugs within 62 px; terrain blocks evasion.'],
 ['Dune guard (custom opt-in)',null,1,'Five pellets, 1 each','1.1 s','Beneath the Dunes custom mission. Eight-direction shotgun, 30 degree total arc, 120 px range; exactly five pellets. Fixed kit; no pickups or cannon mounting; shared troop movement/focus/use orders.'],
 ['Field mechanic (custom opt-in)',null,1,'Rifle 1; repair 0.5 HP/s','0.6 s rifle','Beneath the Dunes custom mission. Eight-direction rifle, 180 px sight. Repairs one living, damaged nearby tank, ground robot or crawler within 62 px with clear sight, up to its normal health cap. Fixed kit; no pickups or cannon mounting; shared troop movement/focus/use orders.'],
 ['Convoy crawler (custom opt-in)',null,6,'Mine: 4 to exposed ground enemies','2 s evade rest; four mines','Beneath the Dunes custom mission. Route travel 30 px/s. Beneath the Dunes crawlers start disabled at 2/6 HP: full repair permanently unlocks travel; keep a living ground escort within 110 px with clear sight. Full 17 px footprint; reacts once to each locked worm lane, evading 32 px on both axes at 100 px/s if the full sweep is clear. After completing evasion drops a mine at its departure point; arms after 0.65 s, expires after 30 s. Mines trigger within 22 px, blast 38 px, terrain blocks damage; no friendly or underground damage. No shield during evasion.'],
 ['Red Krate bug','Krate Ground Bug',specialistRules.redbug.hp,'Spit: 1; melee: 1',`${specialistRules.redbug.fireMin}–${specialistRules.redbug.fireMax} s spit; melee: 1 s`,`Red abdomen band. ${specialistRules.redbug.sight} px sight, blocked by terrain. ${specialistRules.redbug.spawnChance*100}% chance among newly spawned ground bugs from nests, queens and waves. Fixed health/cooldown across difficulties; normal facing cone and randomized behavior. Can evolve into a normal queen.`],
 ['Advanced Krate / queen','Advanced Krate Bug',h.queen,'Spit: 1; melee: 1',`${(base+.4).toFixed(1)}–${(base+2).toFixed(1)} s spit; melee: 1 s`,'Same facing cone and distracted perception as ground bugs; moves more slowly. Spawns one bug every 7 s below the population cap; releases four when killed.'],
 ['Egg / nest','Egg',s.profile?.nestHP||sourceRules.eggHealth||50,'No direct damage',s.customMission?.nestInterval?`Spawn: ${s.customMission.nestInterval} s`:s.profile?`${s.profile.nestRollSuccesses}% opportunity / 0.5 s; birth after 1.8 s`:difficulty==='normal'?'4% opportunity / 0.5 s; birth after 1.8 s':`Spawn: ${(5/(window.TriumphBalance.motionMultipliers[difficulty])).toFixed(1)}–${(9/(window.TriumphBalance.motionMultipliers[difficulty])).toFixed(1)} s`,'Stationary breeding site, spawning ground bugs below the population cap. Original missions: first roll at 0.5 s; 2.4 s busy phase on every setting. Custom missions retain their own cadence. Destroy to stop breeding.'],
 ['Growplant / evolver','growplant','Consumed on contact','None','No attack','A touching ground bug becomes a full-health queen. Commanders consume it on contact to prevent evolution. Normal regenerates it in missions 1–3 on item rolls 22–24, while at most three live plants exist before creation. Placed plants elsewhere remain. Not a bullet-damage target.'],
 ['Troop carrier','Troop Carrier','Not damageable','None','Drops: 1 troop/s while stopped','Follows recovered carrier paths and unloads below the population cap, stopping for at least 5 seconds to deliver a squad. Blocks bug projectiles without taking damage. Incoming support allows commanders to return. Unloaded soldiers attack-move to the nearest reachable rally flag when one exists.'],
 ['Air support','Air Support','Not damageable','Bullet: 1; bomb: 12 to bugs, 2 to nests','Gun: 0.33 s; bomb/drop: 1 s','Flies a straight pass, shoots along its flight direction, bombs nearby enemies and drops commandos over open terrain below the cap. Leaves after its pass. Commandos ignore rally flags, including Blitzkrieg drops.'],
 ['Plasma cannon','cannon','Operator: 1; cannon not damageable','1 direct + six 1-damage sparks','Operator: 0.38 s; Defend: 0.20 s',burstText('soldier')+' Infantry occupies this stationary gun. Detects visible targets within 360 px, retains 16 equally spaced directions (22.5°) visually with either infantry or commando operators. Each burst locks its target center, sweeps smoothly across a random total 0–15° arc, and reverses direction next burst. Commando operators retain 5–7 shots, 0.8–1.2 s rest and 0.2–0.4 s reaction. No armor for operator; attack-move dismounts it.'],
 ['Crystal','Crystal',s.profile?.crystalHP||sourceRules.crystalHealth||7,'None','No attack','Mission objective. Bug bullets/melee each remove 1 HP; destruction loses the mission. Recovery/extraction depends on the mission.'],
 ['Canister / explosive drum','Small explosive canister',4,'Explosion: 8 to bugs, 12 to nests','One explosion','Can chain nearby containers. Leaves fire for 4 s; touching bugs take 1 damage each simulation update. Friendly units and commanders are immune.'],
 ['Breakable wall','Breakable wall',12,'None','No attack','Blocks movement and shots until destroyed.'],
 ['Door','Door','Durability: 5, 15 or indestructible','None','No attack','Closed doors block movement and shots. Terminals unlock linked doors; troops open unlocked doors nearby. Bug bullets remove 1 durability per hit from destructible doors.'],
 ['Terminal','computer area','Not damageable','None','No attack','Operate nearby with Fire, or double right-click with troops selected to send them to activate it. Unlocks linked doors or satisfies mission objectives.']
 ];
 const image=name=>{const o=Object.values(original?.objects||{}).find(o=>o.name===name||o.name?.startsWith(name)),a=Object.values(o?.animations||{})[0],d=Object.values(a||{})[0],handle=d?.frames?.[0]??o?.image;return handle===undefined?'':`<img src="assets/images/${handle}.png" alt="" loading="lazy">`;};
 document.querySelector('#units-context').textContent=`${currentMission().name} · Firing difficulty: ${difficulty} · Bug HP: ${h.bug}, queen HP: ${h.queen}. Health is set at mission start; changing difficulty restarts the mission.${s.customMission?.profile?` Custom ${s.customMission.profile}: ${s.customMission.guards===undefined?s.customMission.soldiers.length+s.customMission.commandos.length:s.customMission.guards+4} starting infantry; ${s.nests.length} nests. ${s.customWaves.arrivals.length} finite arrivals.${s.customMission.nestInterval?` Nest birth interval: ${s.customMission.nestInterval}s.`:''}`:''}${s.customMission?.role==='expedition'?' Whiteout Signal: activate station relay, acquire three soldiers within 70px when three army slots are free, extract one designated living survivor at west pad (80px). Three finite yellow eagle caches provide carrier reinforcements. Party loss after acquisition or army exhaustion loses; enemies may remain.':s.customMission?.role==='capital-defense'?' District Twelve: activate both transit terminals, hold 120 seconds, wait for three scheduled commandos at 70 seconds and all support landing, then clear every finite nest birth and arrival. Empty nests may remain. Two finite yellow eagles; last noncommander loss fails immediately.':s.customMission?.role==='harbor-defense'?` Harbor Watch: hold 120 seconds, exhaust or destroy four finite nests, emit all ${s.customWaves.arrivals.length} arrivals, then clear bugs. Empty nests need not be destroyed. Three finite yellow troop eagles; full cap retains pickup. Losing the last noncommander fails even with support inbound.`:s.customMission?.role==='defense'?' Last Convoy: hold for 120 seconds, emit all ${s.customWaves.arrivals.length} scheduled arrivals and clear enemies with a living noncommander. The last noncommander dying causes defeat even with support inbound.':s.customMission?.role==='infiltration'?' Silent Return: unlock access, activate the laser, then return every living ground human to the extraction zone with a noncommander. At 20s three friendly aircraft from the north drop one commando each in three tight parallel columns with about one soldier sprite of clear horizontal space. Return them too; wait for the schedule and all support arrivals. Enemies and nests may remain.':''}`;
 if(s.customMission)document.querySelector('#units-context').textContent+=' Finite eagle caches: '+s.customMission.support.map(p=>p.type).join(', ')+'; no refill. Custom infantry support waits at full soldier/commando cap including pending landing drops. Carrier unloads only into free slots; specialists, crawlers, tanks and robots retain their existing cap convention.';
 document.querySelector('#unit-cards').innerHTML=rows.map(([name,obj,hp,damage,rate,behavior])=>`<article class="unit-card ${name==='Commando'?'commando-card':name==='Red Krate bug'?'redbug-card':''}"><h3>${image(obj)}${name}</h3><dl><dt>HP</dt><dd>${hp}</dd><dt>Damage</dt><dd>${damage}</dd><dt>Cooldown</dt><dd>${rate}</dd><dt>Defense</dt><dd>No armor / damage reduction</dd></dl><p>${behavior}</p></article>`).join('')+`<article class="unit-card weapons"><h3>Weapons & combat rules</h3><p>Rally flags: yellow ground, bronze support and Blitzkrieg soldier/tank/robot arrivals attack-move to the nearest reachable flag by terrain route distance, then hold nearby. Commandos are excluded. Player orders override rally orders; deleting a flag affects future arrivals.</p><p>Auto gun: 1 damage, 290 px/s, up to 638 px travel. Flame: 1 damage, 0.18 s cooldown (5.56 shots/s), up to 145 px. Plasma: 1 direct damage + six 1-damage sparks on impact; commander cooldown 0.25 s, infantry uses its order cooldown; up to 319 px. Each spark can hit separately. Bug spit: 120 px/s, up to 264 px travel; target detection is 175 px for normal bugs and 200 px for red bugs.</p><p>Walls stop shots and block sight. Bullets hit the opposing team. Commander grenades and support bombs hurt bugs and nests; exploding containers and their fire hurt enemies only. No armor, accuracy stat or defense roll exists. Return shields briefly protect commanders; carriers and aircraft have no damageable health pool. Listed shot rates apply within a burst. Infantry, commandos, robots and tanks rest between bursts, with independently randomized reaction delays. Losing a target ends its burst; reacquiring adds a delay, and switching targets never cancels a rest period. Commanders and aircraft retain continuous fire. AI may also hesitate, skip attacks or lack a firing lane.</p></article>`;
 document.querySelector('#unit-guide').showModal();
}
document.querySelector('#units').onclick=showUnits;
