function perceive(u,items,range=210){const hostile=u.team==='alien';if(hostile)range=Math.min(range,u.type==='redbug'?specialistRules.redbug.sight:175);else range=Math.max(range,u.type==='snow-sniper'?480:u.weapon===2?319:u.type==='tank'?300:u.type==='dune-guard'?120:['rider-scout','field-mechanic'].includes(u.type)?180:u.weapon===1?145:245);if(!u.ai)u.ai={nextScan:s.t+(hostile?.8+rnd()*1.2:.1+rnd()*.2),target:null};const ai=u.ai;if(ai.target&&(ai.target.alive===false||ai.target.hp<=0||dist(u,ai.target)>range||!visible(u,ai.target)))ai.target=null;if(hostile&&ai.target&&s.t>ai.focusUntil){ai.target=null;ai.boredUntil=s.t+1+rnd()*2;ai.nextScan=ai.boredUntil;}if(hostile&&s.t<(ai.boredUntil||0))return null;if(s.t>=ai.nextScan){ai.nextScan=s.t+(hostile?1+rnd()*1.4:.3+rnd()*.4);const isSpray=!hostile&&(u.weapon===1||u.type==='dune-guard');const seen=items.filter(a=>(a.alive||a.hp>0)&&dist(u,a)<range&&visible(u,a)).map(a=>{if(isSpray&&sprayDensity){const r=u.weapon===1?145:120,arc=u.weapon===1?Math.PI/8:Math.PI/12;a.sprayDensity=sprayDensity(u,Math.atan2(a.y-u.y,a.x-u.x),arc,r);}return a;}).sort((a,b)=>{if(isSpray&&(b.sprayDensity||0)!==(a.sprayDensity||0))return (b.sprayDensity||0)-(a.sprayDensity||0);const cost=p=>dist(u,p)+(hostile||['soldier','commander','robot','commando','rider-scout','dune-guard','field-mechanic','snow-sniper'].includes(u.type)?0:Math.min(Math.abs(p.x-u.x),Math.abs(p.y-u.y))*.7);return cost(a)-cost(b);});const previous=ai.target;if(!previous||!seen.includes(previous)){const maxDensity=isSpray&&seen.length?seen[0].sprayDensity||0:0;const topCandidates=isSpray&&seen.length?seen.filter(p=>(p.sprayDensity||0)===maxDensity):seen.slice(0,Math.min(hostile?3:2,seen.length));ai.target=topCandidates.length?topCandidates[Math.floor(rnd()*topCandidates.length)]:null;if(ai.target!==previous){ai.hesitateUntil=s.t+(hostile?.35+rnd()*.6:.08+rnd()*.15);ai.focusUntil=s.t+1.5+rnd()*2;}}}return s.t<(ai.hesitateUntil||0)?null:ai.target;}
